		f = []
		s = []
		for i in u:
			f.append(int(i))
		for i in v:
			s.append(int(i))
		f.reverse()
		s.reverse()
		if len(s) < len(f):
			for i in range(len(f) - len(s)):
				s.append(0)
		else:
			for i in range(len(s) - len(f)):
				f.append(0)
		f.append(0)
		ones = 0
